import hashlib
import binascii

def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    def quote_identifier(name):
        return '"' + name.replace('"', '""') + '"'

    table_names = [
        row[0]
        for row in cursor.execute(
            "SELECT name FROM sqlite_master "
            "WHERE type='table' AND name NOT LIKE 'sqlite_%' "
            "ORDER BY CASE WHEN name='users' THEN 0 WHEN name='user' THEN 1 ELSE 2 END, name"
        ).fetchall()
    ]

    target_table = None
    target_info = None
    for table in table_names:
        info = cursor.execute(f"PRAGMA table_info({quote_identifier(table)})").fetchall()
        columns = [col[1] for col in info]
        if "password" in columns:
            target_table = table
            target_info = info
            break

    if target_table is None:
        return 0

    pk_columns = [col[1] for col in target_info if col[5]]
    table_q = quote_identifier(target_table)
    password_q = quote_identifier("password")
    updated = 0

    if pk_columns:
        pk_q = [quote_identifier(col) for col in pk_columns]
        select_cols = ", ".join(pk_q + [password_q])
        where_clause = " AND ".join(f"{col} = ?" for col in pk_q)
        rows = cursor.execute(
            f"SELECT {select_cols} FROM {table_q} WHERE {password_q} IS NOT NULL"
        ).fetchall()
        update_sql = f"UPDATE {table_q} SET {password_q} = ? WHERE {where_clause}"

        for row in rows:
            *pk_values, password = row
            if password is None:
                continue
            if not isinstance(password, str):
                password = str(password)
            digest = hashlib.sha256((salt + password).encode("utf-8")).digest()
            hashed = binascii.hexlify(digest).decode("ascii")
            cursor.execute(update_sql, (hashed, *pk_values))
            updated += 1
    else:
        rows = cursor.execute(
            f"SELECT rowid, {password_q} FROM {table_q} WHERE {password_q} IS NOT NULL"
        ).fetchall()
        update_sql = f"UPDATE {table_q} SET {password_q} = ? WHERE rowid = ?"

        for rowid, password in rows:
            if password is None:
                continue
            if not isinstance(password, str):
                password = str(password)
            digest = hashlib.sha256((salt + password).encode("utf-8")).digest()
            hashed = binascii.hexlify(digest).decode("ascii")
            cursor.execute(update_sql, (hashed, rowid))
            updated += 1

    conn = getattr(cursor, "connection", None)
    if conn is not None:
        try:
            conn.commit()
        except Exception:
            pass

    return updated
